INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'Lockstitch (stitch class 301, using a needle thread and a separate bobbin thread interlocking inside the fabric) is widely used for garment seams mainly because it offers:', '["The highest possible stretch of any stitch type, ideal for all knitwear","A secure, tight, balanced stitch with good seam appearance on both fabric faces, but with LIMITED stretch, making it well-suited to woven fabric seams that don''t need to stretch, rather than stretch-critical knit seams","Automatic elasticity, making it the standard choice for waistbands","Zero thread consumption compared to other stitch types"]'::jsonb, 'A secure, tight, balanced stitch with good seam appearance on both fabric faces, but with LIMITED stretch, making it well-suited to woven fabric seams that don''t need to stretch, rather than stretch-critical knit seams', 'Lockstitch''s two interlocking threads create a flat, secure, good-looking seam, but the stitch itself has minimal built-in stretch — if a lockstitch seam is used on a knit garment area that needs to stretch (like a t-shirt hem), the STITCHES themselves can pop/break under stretch since the thread has nowhere to give, which is exactly why lockstitch is the standard for woven garments but generally avoided for stretch-critical knit seams.', 2, '{"lockstitch"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'Chainstitch (stitch class 401, using two threads looping together without a bobbin) is often chosen over lockstitch for certain knit garment seams specifically because it:', '["Uses no thread at all","Has inherent stretch/elasticity built into the interlooped structure, allowing the seam to stretch along with a knit fabric without the stitches breaking, unlike the more rigid lockstitch","Always produces a weaker seam than lockstitch in every application","Can only be sewn by hand, never by machine"]'::jsonb, 'Has inherent stretch/elasticity built into the interlooped structure, allowing the seam to stretch along with a knit fabric without the stitches breaking, unlike the more rigid lockstitch', 'Chainstitch''s interlooped (rather than interlocked) thread structure gives it genuine built-in stretch, letting the seam elongate along with a stretchy knit fabric without breaking — this is precisely why chainstitch (and similarly stretch-capable overlock/coverstitch) is preferred over lockstitch for many knit garment seams, despite chainstitch''s known drawback of being prone to unraveling entirely if the thread end isn''t secured (a full chain can ''run'' if pulled from the wrong end).', 3, '{"chainstitch"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'Overlock (overedge) stitching, commonly used to finish raw fabric edges and sew knit garment side seams, serves which PRIMARY function beyond just joining fabric?', '["It has no function beyond simple seam joining, identical to lockstitch","It simultaneously trims the raw fabric edge AND encases/binds it with thread in one operation, preventing fraying while also providing a stretchable seam — a combined edge-finishing and seaming function in a single pass","It only works on woven fabric, never knit fabric","It replaces the need for any cutting step in garment construction"]'::jsonb, 'It simultaneously trims the raw fabric edge AND encases/binds it with thread in one operation, preventing fraying while also providing a stretchable seam — a combined edge-finishing and seaming function in a single pass', 'Overlock machines have a built-in knife that trims the fabric edge just before the looper threads wrap around and encase that trimmed edge — this dual action (trim + edge-finish) in a single pass is what makes overlock efficient for knit garment construction, simultaneously preventing raw-edge fraying/curling while providing a seam with good stretch capability.', 2, '{"overlock-stitch"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'Coverstitch (a specialized multi-needle stitch commonly seen as parallel rows of stitching on t-shirt hems and neckbands) is chosen for hemming knit garments specifically because it:', '["Produces a rigid, non-stretch hem identical to a woven garment''s hem","Combines good stretch (needed for a knit hem to move with the fabric) with a clean, flat, professional-looking finish on both the face (parallel rows) and back (a covering chainstitch loop structure) of the fabric","Can only be used to attach buttons, never for hemming","Requires no special machine, identical to a standard lockstitch machine"]'::jsonb, 'Combines good stretch (needed for a knit hem to move with the fabric) with a clean, flat, professional-looking finish on both the face (parallel rows) and back (a covering chainstitch loop structure) of the fabric', 'Coverstitch machines create a distinctive, recognizable hem structure — parallel straight stitch rows visible on the garment face, with a covering interlooped structure on the back — specifically engineered to provide both the stretch a knit hem needs to move with the body and a clean, durable, professional finished appearance, which is why it''s the industry standard for t-shirt/knitwear hems and neckbands rather than a simple straight lockstitch.', 2, '{"coverstitch"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A quality issue known as ''seam pucker'' (a wavy, rippled appearance along a sewn seam rather than lying flat) can result from multiple root causes. Which of these is generally NOT a typical cause of seam pucker?', '["Excessive thread tension pulling the fabric together more tightly than the fabric itself can accommodate","Mismatched fabric feed rates between the top and bottom fabric plies (differential feeding) during sewing","Using a properly sharp needle appropriate for the fabric type, correctly matched to the fabric''s structure","Fabric structural/inherent puckering from the fabric''s own weave/knit construction, unrelated to the sewing operation itself"]'::jsonb, 'Using a properly sharp needle appropriate for the fabric type, correctly matched to the fabric''s structure', 'A correctly selected, sharp needle matched to the fabric type is a PREVENTIVE factor, not a cause of puckering — the other three options (excessive tension, differential ply feeding, and inherent fabric structural pucker) are all genuine, well-documented causes of seam pucker, making the correctly-matched sharp needle the one factor that actually reduces rather than causes this defect.', 2, '{"seam-pucker"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', '''Marker making'' (arranging pattern pieces on fabric width to maximize fabric utilization before cutting) directly impacts a garment''s production cost mainly through:', '["The garment''s final selling price, set independently of any fabric usage consideration","Fabric utilization/wastage percentage — a more efficient marker (higher fabric utilization%, less unused fabric between pattern pieces) directly reduces the fabric cost per garment, often one of the largest cost components in apparel manufacturing","The sewing machine''s operating speed, unrelated to marker layout","Only the garment''s color, with no cost implication"]'::jsonb, 'Fabric utilization/wastage percentage — a more efficient marker (higher fabric utilization%, less unused fabric between pattern pieces) directly reduces the fabric cost per garment, often one of the largest cost components in apparel manufacturing', 'Since fabric is typically the single largest cost component in a garment''s total manufacturing cost, even small improvements in marker efficiency (the percentage of fabric width/length actually covered by pattern pieces versus wasted as unused scrap between pieces) translate directly into meaningful per-garment cost savings at scale — this is why marker efficiency is a closely tracked, optimized metric in production planning, often using CAD marker-making software to maximize it.', 2, '{"marker-making"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'Computer-Aided Marker Making (CAD-based automatic/semi-automatic marker optimization software) generally achieves HIGHER fabric utilization than manual, hand-drawn marker making mainly because it:', '["Uses a completely different, unrelated cutting technology, not comparable to manual methods","Can algorithmically test many more pattern piece arrangement/rotation combinations within practical time constraints than a human marker maker manually trying layouts by hand, finding tighter-fitting arrangements that a human would take impractically long to discover manually","Always requires MORE fabric than manual marker making, making the comparison backwards","Only works for extremely simple garment styles with no complex pattern pieces"]'::jsonb, 'Can algorithmically test many more pattern piece arrangement/rotation combinations within practical time constraints than a human marker maker manually trying layouts by hand, finding tighter-fitting arrangements that a human would take impractically long to discover manually', 'The fundamental advantage of CAD marker optimization is combinatorial: finding the truly optimal arrangement of many irregularly-shaped pattern pieces is a complex optimization problem, and software can explore vastly more piece rotation/positioning combinations within a practical timeframe than a human manually testing layouts by hand, typically achieving measurably higher fabric utilization percentages, especially as pattern piece count and complexity increase.', 3, '{"CAD-marker-making"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Grading'' (systematically scaling a base pattern up/down to create the full size range, e.g., S/M/L/XL from a base Medium pattern) must be done according to a defined ''grade rule'' for each pattern point, rather than simply scaling the entire pattern uniformly. Why?', '["Uniform scaling would actually work perfectly fine and grade rules are an unnecessary complication","Different body dimensions don''t all change proportionally between sizes (e.g., chest width grows differently than sleeve length or neck opening across a size range), so each pattern point needs its own specific grade rule to accurately reflect real anthropometric size progression, not just a uniform percentage scale-up","Grade rules only apply to children''s wear, never adult sizing","All garment styles use identical grade rules regardless of body area or fit type"]'::jsonb, 'Different body dimensions don''t all change proportionally between sizes (e.g., chest width grows differently than sleeve length or neck opening across a size range), so each pattern point needs its own specific grade rule to accurately reflect real anthropometric size progression, not just a uniform percentage scale-up', 'Real body measurement data shows that different body dimensions scale at different RATES across a size range (e.g., neck circumference typically grows more slowly than chest circumference between sizes) — a uniform percentage scale-up of the whole pattern would distort proportions and produce poorly-fitting larger/smaller sizes, which is exactly why professional grading uses point-specific grade rules derived from actual body measurement progressions rather than simple uniform scaling.', 3, '{"pattern-grading"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', '''Ease'' (the deliberate difference between a garment''s finished measurement and the wearer''s actual body measurement, e.g., a chest measurement 4 inches larger than the body''s actual chest circumference) is a critical pattern-making concept because:', '["Ease has no functional purpose; it exists only as an unintentional pattern-making error","Adequate ease allows for movement, comfort, and layering (wearing over other clothing) — too little ease creates a tight, restrictive, uncomfortable garment, while an intentionally FITTED style deliberately uses minimal ease, showing that ease amount is a deliberate design/fit decision, not a fixed universal constant","Ease is only relevant for outerwear, never for everyday garments like t-shirts","More ease always means a lower-quality garment regardless of the intended style"]'::jsonb, 'Adequate ease allows for movement, comfort, and layering (wearing over other clothing) — too little ease creates a tight, restrictive, uncomfortable garment, while an intentionally FITTED style deliberately uses minimal ease, showing that ease amount is a deliberate design/fit decision, not a fixed universal constant', 'Ease is a deliberate, purposeful pattern-making decision, not an error — the RIGHT amount of ease depends entirely on the garment''s intended fit and function (a loose outerwear jacket needs substantially more ease than a fitted t-shirt or compression legging), which is why pattern makers specify different ease allowances for different garment categories rather than applying one universal ease amount to every style.', 2, '{"ease-allowance"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Fusible interlining'' (bonded to fabric via heat/pressure, e.g., in shirt collars) versus ''sew-in interlining'' (attached by stitching, not heat) — a garment technologist would generally recommend sew-in interlining instead of fusible specifically for:', '["Any standard cotton shirt collar, where fusible is always the technically superior choice","Fabrics that are heat-sensitive, have a pile/nap surface that heat/pressure would crush, or have an uneven surface texture that would show visible fusing imprints (bubbling/witness marks) through the face fabric","There is never a valid reason to prefer sew-in interlining over fusible interlining in any application","Only garments with zero structural requirement, where no interlining is actually needed at all"]'::jsonb, 'Fabrics that are heat-sensitive, have a pile/nap surface that heat/pressure would crush, or have an uneven surface texture that would show visible fusing imprints (bubbling/witness marks) through the face fabric', 'While fusible interlining is faster and generally preferred for compatible fabrics, certain fabric types are poor fusing candidates — heat-sensitive synthetics that could scorch/melt, textured or piled fabrics that heat/pressure would flatten/damage, or fabrics prone to visible ''witness marking'' (the interlining''s texture showing through the face fabric after fusing) — for these, sew-in interlining avoids the heat/pressure application entirely, a deliberate technical material-compatibility decision.', 3, '{"interlining-selection"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'Progressive Bundle System (PBS) — a traditional garment production line where bundles of cut pieces move sequentially from one operator (each doing one specific operation) to the next — has a well-known limitation compared to more modern production systems (like modular/UPS teams). What is it?', '["PBS always produces the highest possible quality with zero limitations","Work-in-process (WIP) inventory builds up between operations at different speeds, creating bottlenecks, longer overall lead time, and making it hard to quickly identify which specific operation caused a quality problem, since bundles from many different points in time can be mixed together at any workstation","PBS requires zero operator training, unlike modular systems","PBS is only usable for producing a single style at a time across an entire factory"]'::jsonb, 'Work-in-process (WIP) inventory builds up between operations at different speeds, creating bottlenecks, longer overall lead time, and making it hard to quickly identify which specific operation caused a quality problem, since bundles from many different points in time can be mixed together at any workstation', 'Because PBS moves fixed bundles sequentially through many individual single-operation stations, imbalances in operation speed cause WIP to pile up at slower (''bottleneck'') stations, extending overall lead time — and because a bundle''s individual pieces might sit for a while before reaching the next operation, tracing exactly when/where a specific defect was introduced becomes harder, which is a key motivation behind modern lean approaches like modular/cellular (UPS) production that emphasize smaller batch sizes and faster, more traceable flow.', 3, '{"production-systems","PBS"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Modular'' or ''Unit Production System'' (UPS) manufacturing, where a small team of cross-trained operators completes most/all operations on a garment (or a small batch moves via an automated overhead transport rather than large manual bundles), is generally favored over traditional PBS when a factory needs:', '["Maximum output of a single, unchanging style with zero flexibility needed, run for years without change","Fast style changeover, shorter lead times, and better real-time quality traceability, since small batch sizes move through the system quickly with less WIP buildup, and cross-trained teams can adapt more readily to frequent style/order changes","The lowest possible operator training investment, since UPS requires no cross-training","Elimination of all quality inspection, since UPS is claimed to be inherently defect-free"]'::jsonb, 'Fast style changeover, shorter lead times, and better real-time quality traceability, since small batch sizes move through the system quickly with less WIP buildup, and cross-trained teams can adapt more readily to frequent style/order changes', 'UPS/modular systems trade some of PBS''s raw single-style throughput efficiency for much greater FLEXIBILITY and speed — smaller batch sizes flow through faster (less WIP sitting idle), cross-trained operators can pivot between styles more readily, and problems are caught closer to real-time — making UPS particularly well suited to fast-fashion, frequent-style-change, or smaller-order production environments compared to PBS''s strength in long, unchanging, high-volume single-style runs.', 3, '{"UPS-modular-system"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', '''Line balancing'' in a garment sewing line (assigning the right number of operators/machines to each operation based on that operation''s SAM, so no single operation becomes a severe bottleneck) is critical because an unbalanced line will show:', '["No effect on production output, since all operators are working simultaneously regardless of balance","Some operators idle/waiting for work while others are overloaded/backed up, since the line''s overall output rate is limited by its SLOWEST (bottleneck) operation, regardless of how fast the other operations run","An automatic, guaranteed increase in fabric utilization, unrelated to labor efficiency","Only a color-matching issue, unrelated to actual production throughput"]'::jsonb, 'Some operators idle/waiting for work while others are overloaded/backed up, since the line''s overall output rate is limited by its SLOWEST (bottleneck) operation, regardless of how fast the other operations run', 'This is the classic bottleneck/constraint principle applied to sewing line design — an assembly line''s overall throughput rate is fundamentally capped by its single slowest operation (the bottleneck); if operator/machine allocation doesn''t match each operation''s actual SAM (standard time) requirement, faster operations sit idle waiting for work while the bottleneck operation falls behind, directly reducing the line''s overall efficiency and output regardless of how much ''total'' capacity exists elsewhere on the line.', 2, '{"line-balancing"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A garment technologist calculates that Operation A on a sewing line has a SAM of 0.8 minutes while Operation B has a SAM of 0.4 minutes. To keep the line balanced (both operations producing at the same output RATE), the correct operator allocation is generally:', '["Assign identical numbers of operators to both operations regardless of their SAM difference","Assign roughly TWICE as many operators (or machines) to Operation A as to Operation B, since Operation A takes twice as long per piece and therefore needs proportionally more parallel capacity to match Operation B''s output rate","Assign MORE operators to Operation B since it has the lower SAM, prioritizing the faster operation","SAM values have no bearing on operator allocation decisions"]'::jsonb, 'Assign roughly TWICE as many operators (or machines) to Operation A as to Operation B, since Operation A takes twice as long per piece and therefore needs proportionally more parallel capacity to match Operation B''s output rate', 'Line balancing requires allocating operator/machine capacity inversely proportional to each operation''s SAM — since Operation A takes twice as long per piece (0.8 vs 0.4 minutes), it needs roughly twice the parallel operator capacity to produce pieces at the SAME rate as Operation B, preventing Operation A from becoming a bottleneck that starves downstream operations of work while upstream operations pile up excess WIP in front of it.', 3, '{"line-balancing","SAM-calculation"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A ''whole garment'' knitting technology (producing a complete, fully-formed sweater with NO cutting or sewing required, directly on specialized flat knitting machines) offers which distinct manufacturing advantage over traditional cut-and-sew knitwear production?', '["It always produces lower quality garments than cut-and-sew methods","Near-total elimination of fabric cutting waste and sewing labor, plus a seamless garment with potentially better comfort (no side seams), though typically at higher machine investment cost and with design/style constraints compared to traditional cut-and-sew flexibility","It cannot produce any garment with shaping, only tubes","It requires MORE total labor than traditional cut-and-sew production"]'::jsonb, 'Near-total elimination of fabric cutting waste and sewing labor, plus a seamless garment with potentially better comfort (no side seams), though typically at higher machine investment cost and with design/style constraints compared to traditional cut-and-sew flexibility', 'Whole garment technology (an advanced extension of seamless/fully-fashioned knitting concepts) knits a complete 3D garment shape directly, eliminating cutting waste and most sewing labor while offering genuine seamless comfort — the tradeoff is significant capital investment in specialized machinery and some design/style limitations compared to the essentially unlimited flexibility of cutting and sewing fabric panels, making it most economical for specific product categories (like fine-gauge sweaters) rather than a universal replacement for cut-and-sew.', 3, '{"whole-garment-knitting"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Spreading'' (laying multiple plies of fabric on top of each other on the cutting table before cutting, sometimes 100+ plies high) increases cutting efficiency but introduces a specific quality risk. What is it?', '["Spreading has no quality risk whatsoever, only benefits","Fabric plies lower in a tall stack can shift/distort slightly during cutting (especially with a straight-knife cutter), and measurement/shade variations can also exist between plies from different points in a fabric roll, so higher stacks require more careful control of tension, alignment, and shade-matching (as discussed in shade sorting) to avoid cutting inaccuracies","Taller spreads always produce MORE accurate cut pieces than shorter spreads with no exception","Spreading eliminates the need for shade sorting entirely"]'::jsonb, 'Fabric plies lower in a tall stack can shift/distort slightly during cutting (especially with a straight-knife cutter), and measurement/shade variations can also exist between plies from different points in a fabric roll, so higher stacks require more careful control of tension, alignment, and shade-matching (as discussed in shade sorting) to avoid cutting inaccuracies', 'While higher spreads improve cutting productivity (more pieces cut per cutting cycle), they introduce real risk: ply shifting/distortion within a tall stack (especially with knife-based rather than laser/waterjet cutting), and the increased chance that plies drawn from very different points along a long fabric roll could have slight shade or dimensional differences — this is precisely why shade sorting/bundling and careful spreading tension control remain important even with automated spreading equipment.', 3, '{"spreading","cutting-room"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'Automated/CNC fabric cutting (e.g., straight-knife, band-knife, or laser cutting systems driven by CAD marker files) offers which specific advantage over fully manual cutting, beyond raw speed?', '["No advantage beyond speed; manual and automated cutting always produce identical accuracy","Highly consistent, repeatable cutting accuracy directly following the digital marker file, reducing piece-to-piece dimensional variation and operator-dependent cutting errors compared to manual cutting, which depends heavily on individual operator skill and consistency","Automated cutting cannot process any fabric type, unlike manual cutting","Automated cutting eliminates the need for any marker making at all"]'::jsonb, 'Highly consistent, repeatable cutting accuracy directly following the digital marker file, reducing piece-to-piece dimensional variation and operator-dependent cutting errors compared to manual cutting, which depends heavily on individual operator skill and consistency', 'Beyond throughput speed, automated cutting''s real quality advantage is CONSISTENCY — since the cutting path is directly driven by the digital marker file rather than a human hand-guiding a cutting tool, piece-to-piece dimensional accuracy is far more repeatable and less dependent on individual operator skill/fatigue/consistency, directly reducing a class of cutting-stage measurement defects that manual cutting is more prone to.', 2, '{"automated-cutting"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'Thread consumption estimation (calculating how much sewing thread a specific garment style will require, per stitch type/seam length) matters for production planning mainly because:', '["Thread cost is completely negligible and never worth estimating in advance","Running out of the correct thread color/lot mid-production causes line stoppages and potential shade mismatch if a different thread lot must be substituted mid-order, so accurate advance thread consumption planning (procurement quantity) avoids both cost overrun and production disruption risk","Thread consumption has no relationship to stitch type, only to garment size","Thread is always purchased in unlimited quantities with no lead time consideration needed"]'::jsonb, 'Running out of the correct thread color/lot mid-production causes line stoppages and potential shade mismatch if a different thread lot must be substituted mid-order, so accurate advance thread consumption planning (procurement quantity) avoids both cost overrun and production disruption risk', 'Thread consumption varies significantly by stitch type (e.g., overlock and coverstitch consume substantially more thread per seam inch than a simple lockstitch, due to their looper thread structure) — accurately estimating total thread needs before production avoids the costly disruption of running out mid-order (causing line stoppages) or having to source an emergency thread batch that might not exactly shade-match the original lot, similar in principle to the fabric shade-lot matching concern.', 2, '{"thread-consumption"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Top of Production'' (TOP) sample approval — inspecting actual samples pulled from the very first units of the REAL bulk production run (not a separate pre-production sample) — serves a purpose distinct from PP sample approval because it specifically confirms:', '["Exactly the same thing as PP sample approval, making TOP approval fully redundant","That the ACTUAL running bulk production line (not just a specially-prepared pre-production sample) is consistently producing garments that meet the approved specification, catching any drift or issue that emerged once full-scale, high-speed bulk production actually began","Only the garment''s packaging, unrelated to the garment''s construction quality","That the fabric supplier''s mill has passed a social compliance audit"]'::jsonb, 'That the ACTUAL running bulk production line (not just a specially-prepared pre-production sample) is consistently producing garments that meet the approved specification, catching any drift or issue that emerged once full-scale, high-speed bulk production actually began', 'A PP sample confirms the process CAN produce an approved garment under careful, controlled conditions, but bulk production at full speed with multiple operators/shifts can introduce drift or issues (consistency degradation, unauthorized shortcuts, worn tooling) that a small, carefully-made PP sample wouldn''t reveal — TOP approval specifically checks the REAL, live production output to confirm this consistency, making it a distinct and necessary checkpoint even after PP sample approval was already obtained.', 3, '{"TOP-sample"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A garment costing sheet breaks total cost into categories like fabric cost, trim cost, CM (Cut-Make, i.e., labor) cost, and overhead. For a typical basic cotton t-shirt, which cost category is usually the LARGEST single component?', '["Trim cost (buttons, labels, hangtags) is almost always the largest single component for any garment type","Fabric cost is typically the largest single component for a basic garment like a t-shirt, since it''s a simple, low-labor-content style where raw material dominates total cost proportionally more than complex, heavily-constructed styles","CM (labor) cost always exceeds fabric cost for every single garment category without exception","Overhead cost is always the single largest category regardless of garment type"]'::jsonb, 'Fabric cost is typically the largest single component for a basic garment like a t-shirt, since it''s a simple, low-labor-content style where raw material dominates total cost proportionally more than complex, heavily-constructed styles', 'For simple, low-construction-complexity garments like basic t-shirts (few operations, low SAM, minimal trims), fabric cost typically dominates the total cost structure — this is different from complex, heavily-constructed garments (e.g., a tailored jacket with many operations and trims) where CM/labor cost can become proportionally much larger; understanding which cost category dominates for a given style helps a merchandiser/costing team know where cost-reduction efforts will have the most impact.', 2, '{"garment-costing"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A factory is comparing two potential fabric suppliers for the same t-shirt order: Supplier X offers fabric at a lower price per kg but with a WIDER GSM tolerance (more variability), while Supplier Y''s fabric costs slightly more but has a TIGHTER GSM tolerance. Beyond the raw fabric cost difference, what hidden cost/risk should the sourcing team weigh?', '["GSM tolerance has no bearing on any downstream cost or quality risk","Wider GSM tolerance from Supplier X increases the risk of garment weight/hand-feel inconsistency across the order, potential customer complaints, and complicates achieving consistent fit/drape across cutting lots, which can translate into hidden quality/rework/rejection costs that may offset the lower raw fabric price","Tighter GSM tolerance always means a WORSE quality fabric, making Supplier Y the objectively wrong choice","GSM tolerance only matters for woven fabric, never for knit t-shirt fabric"]'::jsonb, 'Wider GSM tolerance from Supplier X increases the risk of garment weight/hand-feel inconsistency across the order, potential customer complaints, and complicates achieving consistent fit/drape across cutting lots, which can translate into hidden quality/rework/rejection costs that may offset the lower raw fabric price', 'This connects fabric-stage quality control (GSM consistency, discussed in the quality control and knitting domains) directly to a real sourcing/costing decision — a lower unit price with wider quality tolerance isn''t necessarily the lower TOTAL cost choice once the downstream risk of inconsistent garments, potential buyer rejections, or customer complaints is factored in, illustrating why sourcing decisions should weigh total cost of quality, not just the raw per-kg fabric price.', 3, '{"fabric-sourcing","hidden-cost"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Lean manufacturing'' principles applied to garment production emphasize reducing ''waste'' in seven or eight classic categories (overproduction, waiting, transport, over-processing, inventory, motion, defects, and sometimes unused talent). Applying lean thinking, WHY is excess Work-In-Process (WIP) inventory between sewing operations specifically considered a form of ''waste,'' even though the garments aren''t literally being thrown away?', '["Excess WIP is not actually considered waste in lean manufacturing thinking","Excess WIP ties up capital, floor space, and hides underlying process problems (imbalanced operations, quality issues) since large buffers between stations mask the true, immediate impact of a slow or problematic operation — lean philosophy views this hidden inventory buffer itself as a cost/inefficiency, not just the risk of eventual physical loss","WIP inventory is always beneficial with zero downside from a lean manufacturing perspective","Lean manufacturing principles apply only to fabric/raw material inventory, never to work-in-process between operations"]'::jsonb, 'Excess WIP ties up capital, floor space, and hides underlying process problems (imbalanced operations, quality issues) since large buffers between stations mask the true, immediate impact of a slow or problematic operation — lean philosophy views this hidden inventory buffer itself as a cost/inefficiency, not just the risk of eventual physical loss', 'Lean manufacturing treats inventory (including WIP) as waste not because it necessarily gets discarded, but because it ties up working capital and floor space AND, critically, it masks process problems — with large buffers between operations, a slow or defect-prone station''s impact isn''t immediately visible/felt downstream, delaying detection and correction; this is a core reason lean approaches (like UPS/modular systems) deliberately minimize WIP buffers to expose and force resolution of underlying process issues quickly.', 3, '{"lean-manufacturing","WIP-waste"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'Fully-fashioned garment panels (knit directly to their final shape on a flat knitting machine, requiring minimal cutting) versus cut-and-sew panels (cut from larger flat-knitted fabric) show a key structural quality difference at their edges. What is it?', '["There is no structural difference between the two edge types","Fully-fashioned edges retain their original, self-finished knit loop structure (since they were never cut), generally giving a cleaner, more stable, less bulky edge, while cut-and-sew panel edges are CUT loops that must be secured (e.g., via overlock) to prevent unraveling, since cutting a knit fabric exposes loop ends that can run/unravel if not secured","Cut-and-sew edges are always structurally superior to fully-fashioned edges in every case","Both edge types require identical finishing treatment with no meaningful difference in unraveling risk"]'::jsonb, 'Fully-fashioned edges retain their original, self-finished knit loop structure (since they were never cut), generally giving a cleaner, more stable, less bulky edge, while cut-and-sew panel edges are CUT loops that must be secured (e.g., via overlock) to prevent unraveling, since cutting a knit fabric exposes loop ends that can run/unravel if not secured', 'This connects back to knitting''s run/ladder vulnerability — a fully-fashioned edge was knitted to its final shape and never cut, so its loops remain self-finished and stable; a cut-and-sew edge, by contrast, was cut through a continuous flat-knitted fabric, exposing loop ends at the cut line that are vulnerable to running/unraveling unless properly secured (typically via overlock stitching), which is exactly why fully-fashioned garments (like fine-gauge sweaters) can achieve a cleaner, less bulky edge finish than an equivalent cut-and-sew construction.', 3, '{"fully-fashioned-vs-cut-sew"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A garment factory switching from 100% manual cutting to CNC/automated cutting for a complex, multi-panel jacket style would expect the LARGEST accuracy improvement specifically in which type of pattern piece?', '["Simple, large, rectangular pieces with no curves or intricate detail, which are already easy to cut accurately by hand","Small, intricately curved, or detail-heavy pattern pieces (e.g., collar points, complex facings), where consistent manual cutting accuracy is hardest for a human operator to maintain across many repeated pieces, so automation''s consistency advantage matters most","Automated cutting provides equal improvement across every pattern piece type, with no differentiation based on piece complexity","Pattern piece shape has no bearing on the accuracy improvement automation provides"]'::jsonb, 'Small, intricately curved, or detail-heavy pattern pieces (e.g., collar points, complex facings), where consistent manual cutting accuracy is hardest for a human operator to maintain across many repeated pieces, so automation''s consistency advantage matters most', 'Automated cutting''s consistency advantage over manual cutting is most valuable precisely where manual cutting is hardest to do consistently — small, intricately shaped, or detail-critical pieces (sharp corners, tight curves) are the most prone to human-introduced variation across a large cutting run, so this is where CNC/automated cutting''s repeatable precision provides the greatest relative accuracy improvement compared to simple, large, easy-to-cut pieces where manual accuracy is already relatively easy to maintain.', 3, '{"automated-cutting","pattern-complexity"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', '''Sample yardage'' consumption (fabric used to make development/fit/PP samples before bulk production) is deliberately tracked and minimized in efficient product development processes mainly because:', '["Sample fabric is free and has no cost implication for the brand or factory","Excessive sample-making (many rounds of samples, each consuming fabric that generates no revenue) represents real, avoidable cost and lead-time waste — efficient product development aims to get designs right with fewer sample iterations through better upfront technical specification and virtual/digital sampling tools","Sample fabric consumption has no relationship to overall product development speed or cost","Only bulk production fabric usage matters; sample yardage is never tracked in any real apparel business"]'::jsonb, 'Excessive sample-making (many rounds of samples, each consuming fabric that generates no revenue) represents real, avoidable cost and lead-time waste — efficient product development aims to get designs right with fewer sample iterations through better upfront technical specification and virtual/digital sampling tools', 'Every sample round consumes real fabric, trims, and skilled labor time without generating any revenue, and also adds calendar time to the product development cycle — this is exactly why the industry has invested heavily in tools like 3D virtual sampling/digital prototyping, aiming to catch and resolve fit/design issues with fewer physical sample iterations, directly reducing this non-revenue-generating cost and lead-time burden.', 2, '{"sample-development","product-development-efficiency"}'::text[]);
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', '3D virtual prototyping/sampling software (simulating how a garment will fit and drape on a digital avatar, before making any physical sample) is increasingly adopted in apparel product development mainly to:', '["Completely replace the need for ANY physical sample ever, at every single stage of development including final production approval","Catch obvious fit, proportion, or design issues EARLY and reduce the NUMBER of costly physical sample rounds needed before an acceptable physical sample is achieved — while physical samples are still typically needed for final confirmation, especially of hand-feel and exact drape","Increase the total number of physical samples required at every stage of the process","Only work for garments with zero fit requirements, such as flat accessories"]'::jsonb, 'Catch obvious fit, proportion, or design issues EARLY and reduce the NUMBER of costly physical sample rounds needed before an acceptable physical sample is achieved — while physical samples are still typically needed for final confirmation, especially of hand-feel and exact drape', '3D virtual sampling is generally used as a FRONT-END filtering/iteration tool — it lets designers and technical teams catch and correct obvious proportion, fit, or design issues digitally before committing to physical sample-making, reducing (not eliminating) the number of costly physical rounds needed; final physical samples typically remain necessary since digital simulation still has limitations in accurately replicating exact fabric hand-feel, drape, and fit nuances that only real fabric and a real body/mannequin can confirm.', 2, '{"3D-virtual-sampling"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'Pressing (steam/heat finishing applied to a completed or partially completed garment) serves a functional purpose beyond just cosmetic smoothing. In tailored garment construction specifically, pressing is used to:', '["Only remove wrinkles for visual appearance, with no structural/shaping function","Actively help SHAPE certain garment components (e.g., setting a lapel roll, shaping a curved seam allowance to lie flat, or setting a crease) using heat and moisture to temporarily soften fiber structure, then set that shape as it cools — a genuine construction step, not merely cosmetic finishing","Replace the need for any interlining in structured garment areas","Only apply to knitwear, never to woven tailored garments"]'::jsonb, 'Actively help SHAPE certain garment components (e.g., setting a lapel roll, shaping a curved seam allowance to lie flat, or setting a crease) using heat and moisture to temporarily soften fiber structure, then set that shape as it cools — a genuine construction step, not merely cosmetic finishing', 'In tailored garment construction especially, pressing at specific points during assembly (not just as a final cosmetic step) is a genuine shaping technique — heat and moisture temporarily soften fiber structure enough to be molded into a desired shape (a lapel''s roll line, a curved seam pressed open to lie flat), which then sets as the fabric cools, making ''under-pressing'' during construction as functionally important as the final finishing press, not just a cosmetic afterthought.', 3, '{"pressing","tailoring"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A garment technologist needs to choose between attaching a woven label via direct sewing versus a heat-transfer/printed label for care instructions. A key consideration favoring a sewn woven label over a printed label for LONG-TERM durability is:', '["Printed labels always outlast sewn labels under any washing condition","A sewn woven label''s information (fiber content, care instructions) is less likely to fade or become illegible after many wash cycles compared to some printed/heat-transfer labels, which can degrade (fade, crack, peel) with repeated washing, especially with harsh detergents or high wash temperatures","Label attachment method has no relationship to information legibility over the garment''s lifetime","Sewn labels are always more expensive with no offsetting durability benefit, making them a poor choice in every case"]'::jsonb, 'A sewn woven label''s information (fiber content, care instructions) is less likely to fade or become illegible after many wash cycles compared to some printed/heat-transfer labels, which can degrade (fade, crack, peel) with repeated washing, especially with harsh detergents or high wash temperatures', 'Since care/content labels legally need to remain legible for the practical life of the garment (so consumers can continue to follow correct care instructions), the durability of the labeling METHOD itself matters — woven labels generally hold their printed/woven information better over repeated wash cycles than some printed or heat-transfer methods, which can be more prone to fading, cracking, or peeling over the garment''s lifetime, an important durability consideration beyond just initial cost or appearance.', 2, '{"label-attachment"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A production engineer is evaluating whether to invest in an automated pocket-setting attachment/workstation for a high-volume jeans line. The investment is most easily justified when:', '["The style changes completely every single week with zero repeat volume, making any dedicated automation investment poorly utilized","The specific operation (pocket setting) is performed at very high volume with minimal style variation over time, since automation investment costs are best justified/amortized against high, sustained repeat volume of the SAME operation, rather than highly variable, low-repeat-volume work","Automation should always be applied uniformly to every operation regardless of volume or repeatability, with no cost-benefit analysis needed","Only fully manual operations can ever be cost-effective, making any automation investment inherently unjustifiable"]'::jsonb, 'The specific operation (pocket setting) is performed at very high volume with minimal style variation over time, since automation investment costs are best justified/amortized against high, sustained repeat volume of the SAME operation, rather than highly variable, low-repeat-volume work', 'Automation investment (dedicated attachments, semi-automated workstations) carries real capital cost that''s only economically justified when amortized across high, sustained volume of essentially the SAME repeated operation — a high-volume, relatively stable style like standard jeans pocket-setting is a strong automation candidate, while highly variable, low-repeat-volume fast-fashion operations often remain more economically suited to flexible manual/semi-manual methods, illustrating that automation decisions require genuine volume/repeatability cost-benefit analysis, not blanket application.', 3, '{"automation-investment"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'basic', 'multiple_choice', 'A sewing operator is assigned to an operation with a SAM (Standard Allowed Minute) of 0.6 minutes per piece. Assuming the operator works at 100% efficiency for a full 480-minute shift, the theoretical maximum output for that operation is:', '["288 pieces (480 ÷ 0.6 = 800, so this option is actually incorrect and used as a distractor)","800 pieces, calculated as total available minutes (480) divided by the SAM per piece (0.6 minutes)","0.6 pieces total for the entire shift","480 pieces, ignoring the SAM value entirely"]'::jsonb, '800 pieces, calculated as total available minutes (480) divided by the SAM per piece (0.6 minutes)', 'Theoretical maximum output at 100% efficiency is simply total available production minutes divided by the SAM (time allowed per piece): 480 minutes ÷ 0.6 minutes/piece = 800 pieces — this calculation is the foundation for capacity planning, line balancing, and efficiency% tracking (actual output ÷ this theoretical maximum × 100) throughout garment production management.', 1, '{"SAM-calculation","capacity"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Efficiency%'' on a sewing line, calculated as (Actual Output × SAM) ÷ (Total Operator Minutes Worked) × 100, is a more meaningful productivity metric than simply counting total pieces produced because it:', '["Efficiency% and raw piece count always give identical rankings between lines, making the distinction meaningless","Normalizes for the actual TIME CONTENT/complexity of the specific style being sewn, allowing fair comparison of productivity between lines running DIFFERENT styles (with different SAM values) rather than unfairly rewarding lines running simpler, faster styles just because they produce more raw pieces per hour","Efficiency% only applies to knitwear production, never to woven garment production","Efficiency% is calculated without any reference to SAM, making the described formula incorrect"]'::jsonb, 'Normalizes for the actual TIME CONTENT/complexity of the specific style being sewn, allowing fair comparison of productivity between lines running DIFFERENT styles (with different SAM values) rather than unfairly rewarding lines running simpler, faster styles just because they produce more raw pieces per hour', 'Raw piece count alone unfairly favors lines sewing simpler, lower-SAM styles (which naturally produce more pieces per hour) over lines sewing complex, higher-SAM styles — by multiplying output by SAM (converting pieces into earned minutes) and comparing against actual minutes worked, efficiency% normalizes for style complexity, allowing genuinely fair, apples-to-apples productivity comparison across lines running different styles.', 3, '{"efficiency-calculation"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A garment factory''s technical team notices that a specific seam type consistently fails tensile/seam strength testing on a new stretch-woven fabric (containing a small percentage of elastane), even though the SAME seam type and stitch settings performed fine on 100% cotton woven fabric of similar weight. What is the most likely explanation?', '["Seam strength requirements are identical for all fabric types regardless of stretch content, so this result must be a testing error","The stitch/seam type (likely a lockstitch, with limited inherent stretch) doesn''t accommodate the added stretch capability of the elastane-containing fabric, so under the SAME test tension, the relatively rigid stitching breaks before the fabric''s own stretch capacity is reached — a stitch selection mismatch, not a fabric defect","The fabric must have been mislabeled and does not actually contain any elastane","Seam strength testing cannot be meaningfully performed on stretch woven fabrics at all"]'::jsonb, 'The stitch/seam type (likely a lockstitch, with limited inherent stretch) doesn''t accommodate the added stretch capability of the elastane-containing fabric, so under the SAME test tension, the relatively rigid stitching breaks before the fabric''s own stretch capacity is reached — a stitch selection mismatch, not a fabric defect', 'This directly applies the earlier lockstitch-vs-stretch-fabric mismatch concept to a specific troubleshooting scenario: adding elastane makes the FABRIC more stretchy, but if the STITCH TYPE chosen doesn''t have comparable stretch capability, the relatively inelastic stitching becomes the weak point that fails first under tension — the practical fix is selecting a more stretch-capable stitch/seam type for elastane-containing fabrics, not treating it as a fabric quality defect.', 3, '{"stitch-fabric-mismatch","troubleshooting"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'Digital/automated size-set and sample tracking systems (replacing paper-based sample tracking across a product development calendar with many styles, sizes, and revision rounds) are increasingly adopted mainly to address which practical problem?', '["Digital tracking has no advantage over paper-based systems for garment sample management","Managing potentially thousands of individual sample pieces (multiple styles × multiple sizes × multiple revision rounds × multiple approval stages) manually via paper becomes extremely error-prone and hard to track at scale — digital systems provide real-time visibility, reduce lost/miscommunicated sample status, and speed up the overall approval cycle","Digital tracking systems are purely a cosmetic technology upgrade with no functional benefit over paper records","Paper-based tracking is always superior for accuracy and should never be replaced regardless of order complexity"]'::jsonb, 'Managing potentially thousands of individual sample pieces (multiple styles × multiple sizes × multiple revision rounds × multiple approval stages) manually via paper becomes extremely error-prone and hard to track at scale — digital systems provide real-time visibility, reduce lost/miscommunicated sample status, and speed up the overall approval cycle', 'As product development complexity scales (many styles, each with multiple sizes and multiple revision/approval rounds across multiple physical locations — factory, agent, buyer office), manual paper tracking becomes genuinely error-prone (lost samples, unclear approval status, miscommunication) — digital tracking systems address this real operational pain point by providing centralized, real-time visibility into exactly where each sample is in its approval journey, directly speeding up the overall product development timeline.', 2, '{"digital-sample-tracking"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A ''French seam'' (a self-enclosed seam where raw edges are fully encased inside a second row of stitching, leaving no exposed raw edge on either side) is chosen over a simple single-line seam mainly for:', '["Heavy denim workwear, where raw-edge fraying is not a concern at all","Lightweight, sheer, or fine fabrics (e.g., chiffon, fine cotton lawn) where a visible raw edge or bulky overlock finish would show through or look unrefined, and a fully enclosed, clean seam is valued for both appearance and fray prevention","Only knit stretch fabrics, since French seams have no application on woven fabric","Situations where minimizing sewing time/labor is the only consideration, since French seams are the fastest possible seam type"]'::jsonb, 'Lightweight, sheer, or fine fabrics (e.g., chiffon, fine cotton lawn) where a visible raw edge or bulky overlock finish would show through or look unrefined, and a fully enclosed, clean seam is valued for both appearance and fray prevention', 'French seams require TWO passes of stitching (a deliberate labor/time tradeoff) specifically to fully enclose the raw edge — this extra step is worth it for lightweight or sheer fabrics where any exposed raw edge or bulky seam finish (like overlock) would be visible or uncomfortably bulky, making the clean, enclosed result a specific technical solution for fine-fabric garment quality rather than a general-purpose seam choice.', 2, '{"french-seam"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A ''flat-felled seam'' (commonly seen on jeans'' outer leg seams and shirt side seams), where both raw edges are folded and enclosed then stitched flat with two visible rows of topstitching, is specifically valued for its:', '["Extreme lightness and delicacy, making it ideal for sheer evening wear","High durability and strength (multiple layers of fabric and stitching reinforcing the seam) combined with a flat, non-bulky profile that resists chafing, which is exactly why it''s standard on hard-wearing garments like jeans and workwear","Requirement of zero stitching, using only fabric folding and adhesive","Complete inability to be used on any denim or heavyweight fabric"]'::jsonb, 'High durability and strength (multiple layers of fabric and stitching reinforcing the seam) combined with a flat, non-bulky profile that resists chafing, which is exactly why it''s standard on hard-wearing garments like jeans and workwear', 'The flat-felled seam''s structure (folded, enclosed, double-stitched) creates a genuinely stronger, more durable seam than a simple single seam, while remaining relatively flat and smooth against the skin (reducing chafing) — this combination of durability and comfort/flatness is precisely why it''s the traditional standard for hard-wearing garment categories like denim jeans and workwear rather than delicate fabrics.', 2, '{"flat-felled-seam"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A garment technical designer specifying seam allowance width (e.g., 1cm vs 1.5cm) for a specific style needs to balance which competing factors?', '["Seam allowance width has zero effect on anything and can be set arbitrarily with no consequence","Narrower allowances save fabric and reduce bulk (useful for lightweight/fitted styles) but leave less margin for seam slippage/fraying and less room for future alteration, while wider allowances offer more durability/adjustment margin at the cost of extra fabric consumption and potential bulk","Only the sewing machine''s brand determines the correct seam allowance, unrelated to style or fabric","Wider seam allowances are always objectively superior with no downside in any application"]'::jsonb, 'Narrower allowances save fabric and reduce bulk (useful for lightweight/fitted styles) but leave less margin for seam slippage/fraying and less room for future alteration, while wider allowances offer more durability/adjustment margin at the cost of extra fabric consumption and potential bulk', 'Seam allowance width is a genuine engineering tradeoff decision: narrower allowances suit fitted, lightweight, or fabric-cost-sensitive styles but offer less protection against seam slippage/fraying and no room for future size alteration, while wider allowances provide more durability and alteration margin at the cost of extra fabric usage and potential bulk in a fitted garment — the right choice depends on the specific style, fabric, and durability requirements.', 3, '{"seam-allowance"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Under-collar'' construction on a tailored shirt or jacket (often using a slightly different, sometimes bias-cut or specially treated fabric/interlining compared to the visible top collar) exists specifically to help the collar:', '["Match the exact same fabric and construction as the garment body with zero difference, for simplicity","Roll and sit correctly around the neck with a smooth, professional appearance, since the under-collar''s slightly different construction/bias accommodates the natural curve needed for the collar to lie flat and roll properly rather than standing stiffly or buckling","Have no functional purpose beyond an arbitrary traditional convention with zero technical basis","Eliminate the need for any interlining in the collar area"]'::jsonb, 'Roll and sit correctly around the neck with a smooth, professional appearance, since the under-collar''s slightly different construction/bias accommodates the natural curve needed for the collar to lie flat and roll properly rather than standing stiffly or buckling', 'The under-collar''s distinct construction (often bias-cut or using a slightly different, more pliable fabric/interlining than the top collar) is a genuine functional tailoring technique — it allows the collar assembly to curve and roll naturally around the neck''s contour, rather than sitting stiffly flat or buckling, illustrating that even a seemingly minor construction detail can have a real functional (not just traditional/cosmetic) purpose in achieving correct garment shape.', 3, '{"collar-construction","tailoring"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A garment manufacturer needs to decide between a ''set-in sleeve'' construction (sleeve sewn into a separate armhole opening) and a ''raglan sleeve'' construction (sleeve panel extends in one piece up to the neckline, no separate shoulder seam) for an athletic top. Raglan construction is often preferred for this application mainly because it:', '["Always requires more total fabric and more complex pattern pieces than set-in sleeves, making it a poor choice for cost-sensitive orders","Provides greater freedom of arm movement (no restrictive shoulder seam directly over the movement-critical shoulder joint), which is valuable for athletic/performance garments requiring an unrestricted range of motion","Can only be used on woven fabric, never on knit athletic fabric","Eliminates the need for any seam at all in the sleeve area"]'::jsonb, 'Provides greater freedom of arm movement (no restrictive shoulder seam directly over the movement-critical shoulder joint), which is valuable for athletic/performance garments requiring an unrestricted range of motion', 'Because raglan construction moves the seam line away from the shoulder joint itself (extending diagonally from underarm to neckline instead), it avoids placing a seam directly over the most movement-critical joint area — this generally allows a greater, less restricted range of arm motion compared to a set-in sleeve''s seam sitting right at the shoulder point, which is exactly why raglan construction is a common choice for athletic and performance-oriented garments.', 2, '{"sleeve-construction"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Princess seams'' (curved vertical seams running from shoulder or armhole down through the bust/waist area, used instead of simple darts for garment shaping) are chosen over darts specifically when a designer wants:', '["The garment to have absolutely NO shaping or fit contouring at all, remaining perfectly flat","A smoother, more continuous shaping line across a larger area of the garment, since princess seams can shape multiple body curves (bust, waist, hip) continuously along one seam line, offering more shaping flexibility than a dart''s more localized, single-point shaping effect","To eliminate all seams from the garment entirely, using only darts","Princess seams and darts always produce visually identical results, making the choice purely arbitrary"]'::jsonb, 'A smoother, more continuous shaping line across a larger area of the garment, since princess seams can shape multiple body curves (bust, waist, hip) continuously along one seam line, offering more shaping flexibility than a dart''s more localized, single-point shaping effect', 'Darts provide shaping at one specific, localized point (e.g., just the bust point), while princess seams distribute shaping continuously along an entire curved seam line that can smoothly accommodate multiple body curves in sequence (bust, waist, hip) — this makes princess seams a preferred technique when a more continuous, flowing fitted silhouette across a larger body area is the design goal, compared to a dart''s more localized shaping effect.', 3, '{"princess-seams","garment-shaping"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A technical designer specifying a ''clean finish'' (a folded-under, topstitched raw edge, e.g., at a facing or hem) versus a ''bound edge'' (raw edge encased in a separate strip of bias binding fabric) would choose the bound edge option specifically when:', '["The fabric is extremely thin and would show no bulk difference between the two methods regardless of choice","The fabric is too thick/bulky to fold under cleanly without excessive bulk, or a decorative contrast-color edge finish is specifically desired, since binding adds a visible design element while managing bulk that a simple folded clean finish couldn''t handle as neatly","Clean finish and bound edge are functionally and visually identical, making the choice irrelevant","Bound edges are only used on garments with zero raw edges to begin with"]'::jsonb, 'The fabric is too thick/bulky to fold under cleanly without excessive bulk, or a decorative contrast-color edge finish is specifically desired, since binding adds a visible design element while managing bulk that a simple folded clean finish couldn''t handle as neatly', 'Binding is a deliberate technical choice for two main reasons: managing excess bulk on thick fabrics that wouldn''t fold cleanly under themselves without unwanted bulk, or intentionally adding a decorative, often contrast-colored design element at an edge — both scenarios where a simple folded-under clean finish would either look bulky/unattractive or wouldn''t achieve the desired decorative effect.', 2, '{"edge-finishing"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Piece rate'' wage systems (paying operators per completed piece/operation rather than a fixed hourly wage) are sometimes criticized in garment manufacturing because they can create an incentive conflict. What is it?', '["Piece rate systems have no possible downside and are universally considered ideal with no tradeoffs","Operators may be incentivized to prioritize SPEED (more pieces = more pay) over QUALITY, potentially increasing defect rates if quality checking/accountability isn''t equally rigorous, creating tension between the pay incentive and the desired quality outcome","Piece rate systems always produce higher quality than hourly wage systems, with zero risk of speed-quality tradeoff","Piece rate systems are illegal in every garment manufacturing country and therefore never actually used"]'::jsonb, 'Operators may be incentivized to prioritize SPEED (more pieces = more pay) over QUALITY, potentially increasing defect rates if quality checking/accountability isn''t equally rigorous, creating tension between the pay incentive and the desired quality outcome', 'Piece rate pay creates a direct financial incentive tied purely to output volume — without equally robust quality accountability (e.g., defective pieces not counted toward pay, or in-line quality checks holding operators accountable), this incentive structure can unintentionally encourage prioritizing speed over careful, defect-free work, which is why effective piece-rate systems are typically paired with strong in-line quality checking and defect-based pay adjustments to balance the incentive.', 3, '{"piece-rate-wages"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A garment factory implementing a ''Total Productive Maintenance'' (TPM) program for its sewing machines (proactive, scheduled maintenance rather than only fixing machines after they break down) primarily aims to reduce:', '["The factory''s total number of employees, unrelated to machine performance","Unplanned machine downtime and the associated production stoppages/quality issues (like skipped stitches from a worn needle or timing issue) that reactive ''fix it when it breaks'' maintenance tends to produce, by catching and addressing wear/issues before they cause a failure or quality problem","The factory''s total fabric purchasing cost, which is unrelated to machine maintenance","The need for any operator training whatsoever"]'::jsonb, 'Unplanned machine downtime and the associated production stoppages/quality issues (like skipped stitches from a worn needle or timing issue) that reactive ''fix it when it breaks'' maintenance tends to produce, by catching and addressing wear/issues before they cause a failure or quality problem', 'TPM''s core logic is proactive rather than reactive — scheduled inspection/maintenance (checking needle condition, machine timing, lubrication) catches developing issues before they cause an unplanned breakdown or a quality problem (like skipped stitches from a worn/bent needle or timing drift), directly reducing both unplanned downtime and the defect rate that reactive-only maintenance tends to produce, since problems are caught and fixed before they actually manifest as production failures.', 2, '{"TPM","machine-maintenance"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A quality-conscious factory schedules regular needle replacement (e.g., every 8 production hours) rather than only replacing needles after they visibly break. This proactive replacement policy exists because:', '["Needles never wear out or degrade in performance before an obvious visible break occurs","A needle can develop microscopic wear, burrs, or slight bending that degrades stitch quality (causing skipped stitches, fabric snagging, or thread damage) well BEFORE it visibly breaks, so waiting for an obvious break means accepting a period of degraded, defect-prone sewing quality","Needle replacement has no relationship to stitch quality whatsoever","Needles are the cheapest possible consumable and replacement frequency is purely a cost-minimization decision with no quality basis"]'::jsonb, 'A needle can develop microscopic wear, burrs, or slight bending that degrades stitch quality (causing skipped stitches, fabric snagging, or thread damage) well BEFORE it visibly breaks, so waiting for an obvious break means accepting a period of degraded, defect-prone sewing quality', 'This is a specific application of the TPM/proactive-maintenance principle: needle degradation (dulling, microscopic burrs, slight bending from normal wear) can measurably harm stitch quality and cause fabric damage well before the needle actually visibly breaks — scheduled preventive replacement avoids the otherwise-invisible quality degradation window that a purely reactive ''replace only when broken'' policy would allow to occur undetected.', 3, '{"needle-maintenance"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A garment technologist is deciding fabric grain direction for cutting a bias-cut dress panel versus a straight-grain cut panel of the same pattern shape. The KEY functional difference bias-cutting provides is:', '["No functional difference at all; grain direction only affects appearance, never drape or stretch behavior","Fabric cut on the bias (at roughly 45 degrees to the straight lengthwise/crosswise grain) has inherent stretch/give and a fluid, clingy drape that straight-grain cutting of the identical woven fabric does not have, since bias direction exploits the diagonal ''give'' inherent in a woven fabric''s interlacing structure","Bias cutting eliminates the need for any seam allowance","Bias-cut and straight-grain-cut panels always use identical amounts of fabric with no yield difference"]'::jsonb, 'Fabric cut on the bias (at roughly 45 degrees to the straight lengthwise/crosswise grain) has inherent stretch/give and a fluid, clingy drape that straight-grain cutting of the identical woven fabric does not have, since bias direction exploits the diagonal ''give'' inherent in a woven fabric''s interlacing structure', 'Even a completely non-stretch woven fabric (with zero elastane) exhibits genuine diagonal ''give''/stretch when cut and used on the bias, because the interlaced warp/weft structure can rack/shift diagonally in a way it cannot along the straight grain — this is a real structural/mechanical property exploited deliberately in bias-cut garment design for its fluid, body-skimming drape, at the cost of using MORE fabric (lower yield/marker efficiency) than straight-grain cutting of the same pattern shape.', 3, '{"bias-cutting"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A pattern piece is accidentally cut with its grainline slightly off from the fabric''s true straight grain (e.g., 5 degrees off), even though the piece''s outer shape/dimensions are cut perfectly accurately. What garment problem is this most likely to cause?', '["No problem at all, since only the outer shape dimensions matter for a correctly-fitting garment","The garment panel may hang, twist, or drape incorrectly once worn/finished (e.g., a pant leg that twists around the leg, or a garment that doesn''t hang straight), even though the piece''s measured dimensions were technically accurate — grainline alignment affects how the fabric HANGS, not just its measured size","Grainline has no relationship to how a finished garment hangs or drapes on the body","This type of error can only ever be discovered after the garment has been worn and washed many times"]'::jsonb, 'The garment panel may hang, twist, or drape incorrectly once worn/finished (e.g., a pant leg that twists around the leg, or a garment that doesn''t hang straight), even though the piece''s measured dimensions were technically accurate — grainline alignment affects how the fabric HANGS, not just its measured size', 'Grainline (marked on every pattern piece, indicating how it must align with the fabric''s straight lengthwise grain) is critical because a fabric''s mechanical behavior (how it hangs, drapes, and resists twisting under gravity/wear) depends heavily on grain alignment — a piece cut slightly off-grain can be perfectly accurate in its outer measured dimensions yet still cause a visibly twisted or poorly-hanging garment once worn, illustrating that grainline is a distinct quality parameter from simple dimensional accuracy.', 3, '{"grainline","cutting-defects"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Pattern engineering'' for a specific fabric''s known behavior (e.g., adjusting a pattern to account for a particular fabric''s known shrinkage% or stretch recovery characteristics) is necessary rather than using one universal pattern for every fabric because:', '["All fabrics behave identically once cut and sewn into a garment, regardless of fiber content or structure","Different fabrics have measurably different shrinkage, stretch, and drape behaviors (as established across the spinning, weaving/knitting, and wet processing topics), so a pattern optimized for one fabric''s specific behavior may produce a poorly-fitting garment if blindly reused for a fabric with different mechanical properties","Pattern engineering is a purely theoretical concept with no practical application in real garment production","Only the garment''s color needs to be adjusted for different fabrics, never the pattern itself"]'::jsonb, 'Different fabrics have measurably different shrinkage, stretch, and drape behaviors (as established across the spinning, weaving/knitting, and wet processing topics), so a pattern optimized for one fabric''s specific behavior may produce a poorly-fitting garment if blindly reused for a fabric with different mechanical properties', 'This ties together the whole production chain''s fabric-behavior concepts (shrinkage, crimp, stretch/recovery, drape) into pattern-making practice — since these properties genuinely vary between fabrics (even nominally similar ones from different mills/lots), a pattern must be engineered/adjusted for the SPECIFIC fabric''s known behavior (e.g., adding extra shrinkage allowance for a fabric known to shrink more) rather than assuming one universal pattern will fit correctly regardless of which fabric is actually used.', 3, '{"pattern-engineering"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A garment factory''s technical team is asked to explain why the SAME pattern and cutting specs, used with two different fabric ROLLS of the nominally identical fabric (same style/color/supplier), produced finished garments with slightly different final measurements after washing. What is the most likely explanation, given everything established about fabric variability?', '["This scenario is impossible; fabric from the same supplier and style always behaves identically with zero lot-to-lot variation","Lot-to-lot variation in shrinkage behavior (potentially from differences in loop length/crimp during knitting or weaving, or differences in finishing/compacting between production runs) between the two fabric rolls, even of nominally the same style, can produce measurably different post-wash dimensions from an identical pattern and cutting spec","The sewing operators must have used a different stitch type between the two batches, which is the only possible explanation","Washing machines used in testing must have been different models, which is the only possible explanation"]'::jsonb, 'Lot-to-lot variation in shrinkage behavior (potentially from differences in loop length/crimp during knitting or weaving, or differences in finishing/compacting between production runs) between the two fabric rolls, even of nominally the same style, can produce measurably different post-wash dimensions from an identical pattern and cutting spec', 'This synthesizes concepts from across the production chain — even fabric from the same supplier/style can show real lot-to-lot process variation (different loop length/crimp from knitting, different compacting/finishing effectiveness) that directly affects shrinkage behavior, meaning an identical pattern and cutting process can still yield measurably different finished dimensions after washing if the underlying fabric ROLLS themselves weren''t perfectly consistent — a genuine, well-documented apparel manufacturing quality challenge, not usually attributable to sewing or washing procedure differences alone.', 3, '{"fabric-lot-variation","measurement-consistency"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', '''Garment Construction Sequence'' planning (deciding the precise ORDER in which sewing operations must occur, e.g., attaching a pocket before closing a side seam it would otherwise block access to) matters because an incorrect sequence can:', '["Have no practical consequence, since operations can always be performed in any order with identical results","Make certain later operations physically impossible or extremely difficult to perform correctly (e.g., trying to attach an inner pocket after the side seams are already fully closed, blocking hand/machine access to that area), forcing costly rework or an inferior workaround","Only affect the garment''s color, unrelated to construction feasibility","Always improve production speed regardless of the specific sequence chosen"]'::jsonb, 'Make certain later operations physically impossible or extremely difficult to perform correctly (e.g., trying to attach an inner pocket after the side seams are already fully closed, blocking hand/machine access to that area), forcing costly rework or an inferior workaround', 'Construction sequence isn''t an arbitrary scheduling choice — certain operations genuinely require specific ACCESS (open seam allowances, unclosed edges) that later operations would block if performed out of order, so correct sequence planning is a real technical requirement of garment engineering, and a poorly planned sequence can force operators into difficult workarounds or make an operation essentially impossible to perform to spec.', 2, '{"construction-sequence"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A brand''s technical design team specifies a ''twin needle'' hem (two parallel rows of straight stitching, typically on a lockstitch machine with two needles sharing one bobbin thread looping between them) for a garment that will see high stretch use. Compared to a true coverstitch hem, this choice generally results in:', '["Identical stretch performance to coverstitch, making the two options functionally interchangeable in every application","Reduced stretch capability compared to true coverstitch (since twin-needle lockstitch-based construction has less inherent give than the looped coverstitch structure), making it a less optimal — though sometimes more accessible/cheaper — choice for high-stretch knit hems","Twin needle stitching cannot be performed on any knit fabric, making the comparison moot","Twin needle hems always use less thread than coverstitch hems, with no other functional difference"]'::jsonb, 'Reduced stretch capability compared to true coverstitch (since twin-needle lockstitch-based construction has less inherent give than the looped coverstitch structure), making it a less optimal — though sometimes more accessible/cheaper — choice for high-stretch knit hems', 'While visually somewhat similar (two parallel stitch rows), twin-needle stitching built on a lockstitch-type mechanism has meaningfully less inherent stretch than a true coverstitch''s interlooped structure — for a garment expecting significant stretch use, this is a real functional tradeoff (twin-needle machines being more commonly available/cheaper) versus investing in dedicated coverstitch equipment for genuinely superior stretch performance at the hem.', 3, '{"twin-needle-vs-coverstitch"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A ''topstitch'' (a visible line of stitching sewn through multiple fabric layers near a finished edge, e.g., along a collar or pocket edge) serves which combination of functions?', '["Purely decorative, with zero structural or functional benefit","Both a decorative/design element (visible stitching detail, sometimes in contrast thread color) AND a functional benefit (helping the seam/edge lie flat, adding reinforcement/durability at a stress point, and keeping facing/lining layers from rolling to the outside)","Purely structural reinforcement, with the visible stitching being an unwanted side effect the designer would prefer to hide","Only relevant for denim garments, never used on any other garment category"]'::jsonb, 'Both a decorative/design element (visible stitching detail, sometimes in contrast thread color) AND a functional benefit (helping the seam/edge lie flat, adding reinforcement/durability at a stress point, and keeping facing/lining layers from rolling to the outside)', 'Topstitching genuinely serves a DUAL purpose that technical designers deliberately leverage — it''s a visible design/decorative element (contrast thread color is a common design choice, seen prominently in denim) while ALSO providing real functional benefits: helping a seamed edge lie flat and crisp, adding durability reinforcement at a stress point, and physically preventing an inner facing or lining layer from rolling/peeking out to the visible outer side of the garment.', 2, '{"topstitching"}'::text[]);
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Understitching'' (a line of stitching sewn through the facing and seam allowance only, close to a seam line, NOT visible from the garment''s outer face) at a neckline or armhole facing exists specifically to:', '["Add a visible decorative detail on the garment''s outer face","Keep the facing rolled to the INSIDE of the garment and prevent it from peeking out/rolling to the visible outside, by anchoring the seam allowance to the facing just below the seam line","Replace the need for any facing at all","Increase the garment''s overall stretch capability at the neckline"]'::jsonb, 'Keep the facing rolled to the INSIDE of the garment and prevent it from peeking out/rolling to the visible outside, by anchoring the seam allowance to the facing just below the seam line', 'Understitching is a hidden but functionally important technique — by stitching the seam allowance to the facing (invisible from the outside, since it doesn''t cross to the garment''s face), it anchors the facing''s natural tendency to roll toward the OUTSIDE, keeping it correctly hidden on the inside of the garment for a clean, professional finish at necklines, armholes, and similar facing applications.', 3, '{"understitching"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A garment technologist reviewing a returned/complained-about batch finds the specific failure mode is ''yoke seam popping open under normal arm movement'' on a woven work shirt. Given everything established about stitch types and stress points, what should be checked FIRST?', '["The garment''s color shade, which is unrelated to seam mechanical failure","Whether the yoke seam (a high-stress area during arm movement) was sewn with adequate SPI and appropriate seam type/reinforcement for a stress point, since this mirrors the bar-tack/stress-point reinforcement principle applied to a different specific seam location","The fabric''s colorfastness rating, unrelated to seam strength","Only the button attachment strength, unrelated to the yoke seam issue actually reported"]'::jsonb, 'Whether the yoke seam (a high-stress area during arm movement) was sewn with adequate SPI and appropriate seam type/reinforcement for a stress point, since this mirrors the bar-tack/stress-point reinforcement principle applied to a different specific seam location', 'This applies the general stress-point reinforcement principle (already established for bar tacks at pocket corners/belt loops) to a new specific location — a yoke seam experiences repeated, concentrated stress during arm movement, so a ''seam popping'' complaint should first prompt checking whether that seam received adequate stitch density (SPI) and appropriate seam type/reinforcement for its known high-stress role, rather than investigating unrelated attributes like color or unrelated trim components.', 2, '{"seam-failure","troubleshooting"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A factory technical team is asked why a specific woven fabric requires a LONGER stitch length (fewer SPI) than a typical setting for smooth machine feeding, even though the buyer''s general spec calls for a standard SPI range. What fabric characteristic most likely explains this adjustment?', '["The fabric''s color, which has no relationship to stitch length requirements","A loosely woven, thick, or textured/slubby fabric structure can require a longer stitch length to feed smoothly and avoid excessive needle penetration density that could cause fabric damage (perforation/tearing along the stitch line) in that specific loosely-structured or thick fabric","All fabrics require identical stitch length settings regardless of construction or thickness","Stitch length is determined solely by the sewing machine''s brand, unrelated to fabric properties"]'::jsonb, 'A loosely woven, thick, or textured/slubby fabric structure can require a longer stitch length to feed smoothly and avoid excessive needle penetration density that could cause fabric damage (perforation/tearing along the stitch line) in that specific loosely-structured or thick fabric', 'This connects the earlier SPI-tradeoff principle (too many stitches can perforate/weaken fabric along the seam line) to a specific fabric-property-driven adjustment — thick, loosely-structured, or textured (e.g., slub) fabrics may need a longer stitch length than the ''standard'' setting specifically to avoid excessive needle penetration density damaging that particular fabric''s structure, illustrating that SPI specs sometimes need fabric-specific technical adjustment rather than blanket application of one universal number.', 3, '{"SPI","fabric-specific-adjustment"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A ''dart'' in pattern making creates three-dimensional shape from flat fabric by removing a wedge-shaped section and stitching the resulting edges together. The dart''s POINT (tip) must generally taper to a fine point rather than end abruptly with a squared-off edge, because:', '["Dart point shape has no effect on the finished garment''s appearance","An abruptly-ended (squared-off) dart tip creates a visible pucker/pucker-point at the end of the dart on the garment''s outer face, while a properly tapered, fine point blends smoothly into the flat fabric with no visible endpoint disruption","Dart points are only ever sewn by hand, making machine tapering irrelevant","A squared-off dart tip always makes the garment fit better than a tapered one"]'::jsonb, 'An abruptly-ended (squared-off) dart tip creates a visible pucker/pucker-point at the end of the dart on the garment''s outer face, while a properly tapered, fine point blends smoothly into the flat fabric with no visible endpoint disruption', 'A dart''s shaping effect must transition smoothly from ''fabric removed'' (wide end) to ''no shaping'' (the point) — if the stitching abruptly stops at a wide point rather than tapering to a fine, gradually-narrowing tip, the sudden transition creates a visible pucker or bubble right at the endpoint on the garment''s face, which is why correct dart-point tapering technique (and often a small backstitch/knot at the very tip rather than a wide finish) is a specific, checked construction quality detail.', 3, '{"dart-construction"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', '''Ease-basting'' or ''gathering stitches'' used before setting a sleeve into a fitted armhole (where the sleeve cap circumference is deliberately slightly LARGER than the armhole opening) serves which function?', '["To make the sleeve cap circumference EQUAL to the armhole opening by removing excess fabric before sewing","To allow the slightly larger sleeve cap fabric to be smoothly, evenly eased/distributed into the slightly smaller armhole opening WITHOUT visible puckers, tucks, or gathers, creating the smooth, rounded sleeve cap shape needed for proper fit and appearance over the shoulder/arm curve","To add a decorative gathered/ruffled design effect at the sleeve cap, unrelated to fit","To eliminate the need for any armhole seam at all"]'::jsonb, 'To allow the slightly larger sleeve cap fabric to be smoothly, evenly eased/distributed into the slightly smaller armhole opening WITHOUT visible puckers, tucks, or gathers, creating the smooth, rounded sleeve cap shape needed for proper fit and appearance over the shoulder/arm curve', 'A well-fitted sleeve cap is deliberately pattern-drafted slightly LARGER than the armhole it will be sewn into (this extra fabric, called ''ease,'' is what allows the sleeve to curve smoothly over the rounded shoulder/arm rather than sitting flat) — ease-basting stitches let a sewer gently gather/distribute this intentional excess evenly around the cap during sewing, avoiding the visible puckers or tucks that would result from trying to force the larger fabric into the smaller opening without this controlled easing technique.', 3, '{"sleeve-setting","ease"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A production technical team decides to add a ''clean room'' or dust-controlled area specifically for packing white/light-colored garments, separate from the general finishing area. The technical justification is:', '["Dust/lint contamination has no visible effect on light-colored finished garments","Airborne dust, lint, and fiber fly (byproducts of cutting, sewing, and pressing operations) are far more visible as contamination on light/white garments than on dark garments, so a controlled, lower-particulate environment specifically protects the appearance of light-colored finished goods before final packing","Clean rooms are only relevant for electronics manufacturing, never for garment production","Dark garments require MORE dust control than light garments, making this decision backwards"]'::jsonb, 'Airborne dust, lint, and fiber fly (byproducts of cutting, sewing, and pressing operations) are far more visible as contamination on light/white garments than on dark garments, so a controlled, lower-particulate environment specifically protects the appearance of light-colored finished goods before final packing', 'This is a practical, defect-prevention-driven facility design decision — general production areas naturally accumulate airborne lint/dust/fiber fly from cutting and sewing operations, and this contamination is FAR more visually obvious on light or white fabric than on dark fabric, so protecting light-colored goods'' final appearance (avoiding a ''dirty-looking'' garment defect) justifies extra environmental control specifically at the final packing stage for that product category.', 2, '{"packing-environment","light-colored-goods"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A garment factory is evaluating whether to invest in an automated folding and packing machine for a very high-volume, standardized basic t-shirt program. Similar to the earlier automated pocket-setting decision, the key factor favoring this investment is:', '["The order has highly variable folding/packing specs that change with every single shipment, with no standardization at all","High, sustained volume of a standardized, repeatable folding/packing specification, since automation investment is best justified against high-volume, low-variability repeated tasks rather than highly variable, low-repeat-volume work","Automated folding machines are equally cost-justified regardless of volume or specification variability","The factory should automate this step ONLY if labor costs are extremely low, making automation counterproductive by definition"]'::jsonb, 'High, sustained volume of a standardized, repeatable folding/packing specification, since automation investment is best justified against high-volume, low-variability repeated tasks rather than highly variable, low-repeat-volume work', 'This is the same automation cost-justification principle applied earlier to pocket-setting, now applied to finishing/packing — automated folding/packing equipment investment makes the most economic sense when amortized against high, sustained volume of a STANDARDIZED, repeatable spec, while highly variable, low-volume, frequently-changing pack specs remain better suited to flexible manual packing, reinforcing that automation decisions in garment manufacturing consistently hinge on volume/repeatability analysis.', 2, '{"automation-investment","packing"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A ''hang tag'' (a removable paper/card tag attached to a garment, typically containing brand, price, and sometimes size information) is generally attached using a plastic ''tagging gun'' with a barbed plastic filament (tag pin), rather than simply threaded on a string through a buttonhole or similar opening. A specific QC concern with tagging guns, especially for children''s wear, is:', '["Tagging guns have no quality or safety concerns whatsoever in any application","The tag pin itself, if improperly inserted (e.g., through a double layer of fabric in a way that creates a small hole, or if the barb doesn''t seat correctly), can create a small hole/defect in the garment, and more critically, small detachable tag pins can pose a choking hazard for infants/toddlers if a tag is later removed carelessly, leaving a sharp fragment","Tagging guns are exclusively used for shoes, never for garments","There is no meaningful difference between tagging guns and any other tag attachment method from a quality/safety perspective"]'::jsonb, 'The tag pin itself, if improperly inserted (e.g., through a double layer of fabric in a way that creates a small hole, or if the barb doesn''t seat correctly), can create a small hole/defect in the garment, and more critically, small detachable tag pins can pose a choking hazard for infants/toddlers if a tag is later removed carelessly, leaving a sharp fragment', 'This extends the earlier children''s-wear safety principle (needle detection, button pull strength) to another small-parts risk — tag pins share the same fundamental small, detachable, potentially sharp/hard object concern as buttons/snaps, which is why many children''s wear specs restrict or specifically control hang tag attachment methods, alongside the simpler quality concern of tag guns creating unwanted small holes if improperly inserted through the garment fabric itself.', 3, '{"hang-tag-attachment","safety"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A merchandiser reviewing two competing factory quotes for the same garment style notices Factory A''s quote has a notably LOWER CM (Cut-Make labor) cost than Factory B, despite both claiming similar SAM values for the style. What should the merchandiser investigate before assuming Factory A is simply more efficient?', '["Nothing further needs investigation; the lower quote should always be accepted automatically without any further diligence","Whether Factory A''s lower CM reflects genuinely higher line efficiency/better technology, OR potentially reflects lower wage rates, different labor compliance standards, or an unrealistically optimistic (and likely to be revised upward later) cost estimate — since identical SAM with different CM pricing could stem from several very different underlying causes with different risk implications","CM cost differences between factories are always due to pure luck and cannot be meaningfully investigated","SAM values and CM cost are entirely unrelated figures with no logical connection worth cross-checking"]'::jsonb, 'Whether Factory A''s lower CM reflects genuinely higher line efficiency/better technology, OR potentially reflects lower wage rates, different labor compliance standards, or an unrealistically optimistic (and likely to be revised upward later) cost estimate — since identical SAM with different CM pricing could stem from several very different underlying causes with different risk implications', 'Since CM cost is fundamentally SAM (time content) multiplied by an effective labor rate (adjusted for efficiency/overhead), two factories quoting the SAME SAM but different CM prices must differ in labor rate, actual achieved efficiency, overhead allocation, or profit margin assumptions — a prudent merchandiser investigates WHICH of these explains the gap, since a low quote from lower wage rates or compliance costs carries different sourcing risk implications than one from genuinely superior operational efficiency, and an unrealistically low quote may simply be revised upward once production actually begins.', 3, '{"CM-costing","sourcing-diligence"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A technical team is auditing a factory''s ''right first time'' (RFT) rate — the percentage of garments passing all quality checks WITHOUT requiring any rework — as a production efficiency metric, separate from the final defect/reject rate. Why track RFT separately from just the final pass/fail rate?', '["RFT and final pass rate always measure exactly the same thing, making separate tracking pointless","A garment can eventually PASS after rework (contributing to a good final pass rate) while still having required costly, time-consuming rework along the way — RFT specifically captures this hidden inefficiency (rework cost/time), which a simple final pass/fail metric alone would completely miss","RFT is only relevant for automotive manufacturing, never applicable to garment production","Tracking RFT has no practical use since rework is always free and instantaneous with no cost implication"]'::jsonb, 'A garment can eventually PASS after rework (contributing to a good final pass rate) while still having required costly, time-consuming rework along the way — RFT specifically captures this hidden inefficiency (rework cost/time), which a simple final pass/fail metric alone would completely miss', 'This is a subtle but important production efficiency insight — a high FINAL pass rate can mask significant hidden cost/inefficiency if many of those ''passing'' garments only passed after additional rework time/labor was invested; RFT specifically isolates and measures this rework burden (garments correct on the very first attempt, no correction needed), giving visibility into a real cost/efficiency dimension that final-inspection-only metrics would otherwise hide entirely.', 3, '{"right-first-time","efficiency-metrics"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A ''gusset'' (an extra diamond or triangular fabric piece inserted at a high-stress junction, e.g., underarm of a fitted knit top or the crotch of leggings) is added specifically to:', '["Add a purely decorative design detail with no functional purpose","Provide extra fabric/ease at a point of concentrated body movement stress, reducing the risk of seam failure or restrictive tightness at that junction during movement, similar in underlying principle to bar tacks and raglan sleeves addressing movement-critical areas","Eliminate the need for any seam at that location entirely","Only apply to woven tailored garments, never to knitwear"]'::jsonb, 'Provide extra fabric/ease at a point of concentrated body movement stress, reducing the risk of seam failure or restrictive tightness at that junction during movement, similar in underlying principle to bar tacks and raglan sleeves addressing movement-critical areas', 'A gusset addresses the same underlying engineering problem as bar tacks (concentrated stress points) and raglan sleeves (movement-critical joints) but via a different technique — inserting extra fabric area specifically at a junction where multiple seams meet and the body moves significantly (underarm, crotch), giving the garment enough ease at that exact point to move with the body without tearing or restricting motion.', 2, '{"gusset-construction"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A technical designer chooses to place a garment''s main label (brand/size) via a ''tearaway'' or removable attachment method for certain performance/athletic products, rather than a permanently sewn-in label. The main functional reasoning is:', '["Tearaway labels are always cheaper with no other consideration involved","Some wearers find a stiff, permanently sewn neck label irritating/chafing during high-intensity activity, so a removable option lets the end user eliminate that specific irritation point without damaging the garment, directly addressing a real performance-wear comfort complaint","Tearaway labels are required by law for all activewear in every market","This choice has no relationship to wearer comfort or performance use"]'::jsonb, 'Some wearers find a stiff, permanently sewn neck label irritating/chafing during high-intensity activity, so a removable option lets the end user eliminate that specific irritation point without damaging the garment, directly addressing a real performance-wear comfort complaint', 'This is a genuine, well-known real-world comfort complaint in performance/athletic apparel — a stiff or scratchy neck label can become a distracting irritation point during high-intensity movement and sweating, so offering a cleanly tearaway/removable label option lets the wearer solve this specific comfort issue themselves without damaging the garment''s actual construction, a deliberate design response to documented end-user feedback.', 2, '{"label-design","wearer-comfort"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A garment technologist reviewing construction options for a reversible jacket (wearable on either side) identifies that seam allowances and interior construction details need special handling compared to a standard non-reversible jacket. Why?', '["Reversible garments require no special construction consideration whatsoever, identical to standard construction","Since BOTH the inside and outside of a reversible garment are visible to the wearer/observer depending on which way it''s worn, seam allowances, raw edges, and interior construction elements that would normally be hidden inside a standard garment must instead be fully finished/enclosed, since there''s no truly ''hidden inside'' in a reversible design","Reversible garments never have any seams at all, making the question moot","Only the outer fabric matters in a reversible garment; the inner fabric''s construction quality is irrelevant"]'::jsonb, 'Since BOTH the inside and outside of a reversible garment are visible to the wearer/observer depending on which way it''s worn, seam allowances, raw edges, and interior construction elements that would normally be hidden inside a standard garment must instead be fully finished/enclosed, since there''s no truly ''hidden inside'' in a reversible design', 'This extends the French seam/clean-finish logic to its most demanding case — because a reversible garment has NO permanently hidden interior (either face could be the visible ''outside'' depending on how it''s worn), every seam and raw edge must be constructed to look acceptable from BOTH sides, which is exactly why reversible garment construction typically requires more labor-intensive techniques (like fully enclosed seams) than a standard garment where only one side ever needs a finished appearance.', 3, '{"reversible-garment-construction"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A production planner scheduling a new order onto an existing sewing line factors in the line''s ''learning curve'' — the expectation that efficiency will be LOWER during the first few days of a new style before gradually reaching a stable target efficiency%. This concept exists because:', '["Efficiency is always identical from the very first piece onward, with no ramp-up period, making learning curve planning unnecessary","Operators need a period of practice/adjustment to become fully proficient at the NEW style''s specific operations, especially if it differs meaningfully from the previous style they were running, so realistic production planning must account for this temporary lower-efficiency ramp-up period rather than assuming full target efficiency from day one","Learning curve effects only apply to completely new, first-time employees, never to experienced operators switching styles","Learning curve is a purely theoretical academic concept with no practical bearing on real delivery date planning"]'::jsonb, 'Operators need a period of practice/adjustment to become fully proficient at the NEW style''s specific operations, especially if it differs meaningfully from the previous style they were running, so realistic production planning must account for this temporary lower-efficiency ramp-up period rather than assuming full target efficiency from day one', 'Even experienced operators need to adjust to a new style''s specific operation sequence, handling requirements, and machine setup — this genuine, measurable ramp-up period (efficiency starting lower and gradually climbing to a stable target over the first several days) must be factored into realistic delivery date and capacity planning, since assuming full target efficiency from the very first piece of a new style would lead to systematically overoptimistic (and likely missed) delivery commitments.', 2, '{"learning-curve","production-planning"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A ''style/size ratio'' planning error (cutting and producing garments in a size distribution that doesn''t match actual expected sales demand by size, e.g., overproducing size Small while underproducing size Large relative to real demand) creates which specific business problem, distinct from a pure total-quantity forecasting error?', '["No real problem, since total units produced still matches the total order quantity","Even with the CORRECT total quantity produced, a mismatched size ratio results in stockouts of popular sizes (lost sales) alongside excess unsold inventory of less-popular sizes (markdown/liquidation losses) — a distinct, size-specific planning failure that overall quantity accuracy alone doesn''t prevent","Size ratio planning is entirely the responsibility of the retail store, with zero connection to factory production planning","Size ratio errors only affect children''s wear, never adult sizing"]'::jsonb, 'Even with the CORRECT total quantity produced, a mismatched size ratio results in stockouts of popular sizes (lost sales) alongside excess unsold inventory of less-popular sizes (markdown/liquidation losses) — a distinct, size-specific planning failure that overall quantity accuracy alone doesn''t prevent', 'This highlights that TOTAL quantity accuracy and SIZE RATIO accuracy are two distinct planning dimensions — a factory can produce exactly the right total number of units while still causing real business harm (lost sales from stockouts in popular sizes, markdown losses from excess in less-popular sizes) if the size breakdown doesn''t match actual size-specific demand, which is why accurate size-ratio forecasting (informed by grading/fit data and historical size-specific sell-through) is a distinct planning discipline from simple total-volume forecasting.', 3, '{"size-ratio-planning"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'intermediate', 'multiple_choice', 'A technical package specifies a ''critical measurement point'' list (a subset of all garment measurement points flagged as especially important for fit/function, e.g., chest width and sleeve length on a shirt) distinct from the FULL measurement spec sheet. Why maintain this distinction rather than treating all measurement points as equally critical?', '["All measurement points are always exactly equally important for every garment style, making any distinction meaningless","Some measurement points have a much larger practical impact on perceived fit/function if they deviate (e.g., chest width directly affects wearability), while others are more cosmetic/minor (e.g., a small pocket placement variance) — flagging critical points helps focus limited quality inspection time/attention on the measurements that matter most for actual customer satisfaction and fit","Critical measurement points are determined randomly with no relationship to actual fit impact","Maintaining two separate lists is purely a paperwork formality with zero practical quality management benefit"]'::jsonb, 'Some measurement points have a much larger practical impact on perceived fit/function if they deviate (e.g., chest width directly affects wearability), while others are more cosmetic/minor (e.g., a small pocket placement variance) — flagging critical points helps focus limited quality inspection time/attention on the measurements that matter most for actual customer satisfaction and fit', 'This mirrors the critical/major/minor defect classification principle applied specifically to measurement points — not every measurement deviation has equal real-world consequence, so flagging a smaller set of especially fit-critical points lets inspection resources and attention concentrate on the measurements most likely to cause genuine customer dissatisfaction if out of tolerance, rather than treating a minor cosmetic measurement with the same scrutiny as a core fit dimension.', 2, '{"critical-measurement-points"}'::text[]),
('3c09b2b2-10bd-4e1e-a51d-661d013948bc', 'advanced', 'multiple_choice', 'A factory technical team is asked to reduce garment ''twisting'' (a defect where side seams spiral around the body rather than hanging straight, distinct from the fabric-level spirality defect discussed in knitting) that appears specifically AFTER washing, even though garments measured straight and true immediately after sewing. Given the knitting-stage root cause already established for a related defect, what should be checked first?', '["Only the sewing operation itself, ruling out any fabric-stage cause without investigation","Whether the fabric used had underlying spirality (residual yarn twist torque) that wasn''t fully evident/relaxed before cutting and sewing, since this latent fabric-level distortion can become visible as garment twisting only after the wash relaxes the fabric further — directly connecting back to the yarn-twist-liveliness root cause established in the knitting domain","The color of the thread used in construction, unrelated to any twisting defect","This defect can only be caused by an error in the marker making, with no possible fabric-stage cause"]'::jsonb, 'Whether the fabric used had underlying spirality (residual yarn twist torque) that wasn''t fully evident/relaxed before cutting and sewing, since this latent fabric-level distortion can become visible as garment twisting only after the wash relaxes the fabric further — directly connecting back to the yarn-twist-liveliness root cause established in the knitting domain', 'This directly connects the garment-level ''twisting after wash'' complaint back to the fabric-level spirality root cause already established (residual yarn twist torque from high-twist singles yarn) — because this latent distortion may not be fully visible in the fabric or garment until washing further relaxes the structure, garments can measure straight immediately after sewing yet still develop visible seam twisting only after the customer''s first wash, making fabric-stage yarn twist quality (not a sewing or marker-making error) the first, most likely root cause to investigate.', 3, '{"garment-twisting","root-cause"}'::text[]);
